class PriceEngine:
    def __init__(self):
        self.pricing_strategy = {
            'basic': lambda amount: round(amount, 2),
            'pro': lambda amount: round(amount * 0.9, 2)
        }

    def price(self, plan, amount):
        if plan not in self.pricing_strategy:
            raise KeyError(f"Unknown plan: {plan}")
        return self.pricing_strategy[plan](amount)

# Example usage:
price_engine = PriceEngine()

# Basic plan pricing
basic_price = price_engine.price('basic', 100.00)
print(f"Basic plan price: {basic_price}")

# Pro plan pricing with discount
pro_price = price_engine.price('pro', 100.00)
print(f"Pro plan price: {pro_price}")

# Attempting to use an unknown plan
try:
    unknown_price = price_engine.price('unknown', 100.00)
except KeyError as e:
    print(e)

class PriceEngine:
    DISCOUNT_RATE = 0.10  # 10% discount for the 'pro' plan

    def __init__(self):
        self.plans = {
            'basic': 0.0,  # Basic plan has no discount
            'pro': self.DISCOUNT_RATE  # Pro plan has a 10% discount
        }

    def price(self, plan, amount):
        # Check if the plan is valid
        if plan not in self.plans:
            raise KeyError(f"Unknown plan '{plan}'. Available plans are: {', '.join(self.plans.keys())}")

        # Calculate price based on the plan
        price = amount * (1 - self.plans[plan])

        # Round the price to 2 decimal places
        return round(price, 2)

# Example usage:
price_engine = PriceEngine()
try:
    print(price_engine.price('basic', 100))  # Expected output: 100.00
    print(price_engine.price('pro', 100))    # Expected output: 90.00
    print(price_engine.price('unknown', 100))  # Expected to raise KeyError
except KeyError as e:
    print(e)

class PriceEngine:
    def __init__(self):
        self.basic_price = 0
        self.pro_price = 0

    def set_prices(self, basic_price, pro_price):
        self.basic_price = round(basic_price, 2)
        self.pro_price = round(pro_price, 2)

    def price(self, plan, amount):
        if plan == 'basic':
            return self.basic_price * amount
        elif plan == 'pro':
            discounted_price = self.pro_price * amount * 0.9
            return round(discounted_price, 2)
        else:
            raise KeyError(f"Unknown plan: {plan}")

# Example usage:
price_engine = PriceEngine()
price_engine.set_prices(basic_price=10.00, pro_price=9.00)

try:
    print(price_engine.price('basic', 5))  # Should print 50.00
    print(price_engine.price('pro', 5))    # Should print 40.50
    print(price_engine.price('unknown', 5))  # Should raise KeyError
except KeyError as e:
    print(e)

class FeatureFlags:
    def __init__(self):
        self._flags = {}

    def set(self, name, enabled):
        self._flags[name] = enabled

    def get(self, name):
        return self._flags.get(name, False)

    def export(self):
        # Returns a dictionary with all feature flags
        return self._flags.copy()

# Example usage:
