feature_flags.set('new_feature', True)
print(feature_flags.get('new_feature'))  # Output: True
print(feature_flags.get('unknown_feature'))  # Output: False
print(feature_flags.export())  # Output: {'new_feature': True}

class FeatureFlags:
    def __init__(self):
        self.flags = {}

    def set(self, name, enabled):
        if not isinstance(name, str) or not isinstance(enabled, bool):
            raise ValueError("Name must be a string and enabled must be a boolean.")
        self.flags[name] = enabled

    def get(self, name):
        return self.flags.get(name, False)

    def export(self):
        return self.flags

# Example usage:
feature_flags = FeatureFlags()
feature_flags.set('new_feature', True)
print(feature_flags.get('new_feature'))  # Output: True
print(feature_flags.get('unknown_feature'))  # Output: False
print(feature_flags.export())  # Output: {'new_feature': True}

class FeatureFlags:
    def __init__(self):
        self.flags = {}

    def set(self, name, enabled):
        if name in self.flags:
            self.flags[name] = enabled
        else:
            raise ValueError(f"Unknown feature flag: {name}")

    def get(self, name):
        if name in self.flags:
            return self.flags[name]
        else:
            return False

    def export(self):
        # Returns a copy of the flags dictionary
        return self.flags.copy()

# Example usage:
feature_flags = FeatureFlags()
feature_flags.set('new_feature', True)
print(feature_flags.get('new_feature'))  # Output: True
print(feature_flags.get('unknown_feature'))  # Output: False

# Exporting the feature flags
exported_flags = feature_flags.export()
print(exported_flags)  # Output: {'new_feature': True}

class Permissions:
    def __init__(self):
        self.permissions = {
            'viewer': {'read': True},
            'editor': {'read': True, 'write': True}
        }

    def allowed(self, role, action):
        # Check if the role exists in the permissions dictionary
        if role in self.permissions:
            # Check if the action is allowed for the role
            return self.permissions[role].get(action, False)
        else:
            # If the role is not recognized, deny the action
            return False

# Example usage:
permissions = Permissions()

# Check if a viewer can read
print(permissions.allowed('viewer', 'read'))  # Output: True

# Check if a viewer can write
print(permissions.allowed('viewer', 'write'))  # Output: False

# Check if an editor can read
print(permissions.allowed('editor', 'read'))  # Output: True

# Check if an editor can write
print(permissions.allowed('editor', 'write'))  # Output: True

# Check with an unknown role
print(permissions.allowed('unknown_role', 'read'))  # Output: False

class EventStore:
    def __init__(self):
        self.records = {}

    def record(self, user, value):
        # Check if the user already exists in the store
        if user in self.records:
            # Update the latest value for the user
            self.records[user] = value
        else:
            # Create a new entry for the user with the current value
            self.records[user] = value

    def latest(self, user):
        # Return the latest value for the user, or None if the user does not exist
        return self.records.get(user, None)

# Example usage:
event_store = EventStore()
event_store.record('user1', 'value1')
event_store.record('user1', 'value2')
event_store.record('user2', 'value3')

print(event_store.latest('user1'))  # Output: 'value2'
print(event_store.latest('user2'))  # Output: 'value3'
print(event_store.latest('user3'))  # Output: None

class EventStore:
    def __init__(self):
        self.store = {}

    def record(self, user, value):
        if user not in self.store:
            self.store[user] = []
        self.store[user].append(value)

    def latest(self, user):
        if user in self.store:
            return self.store[user][-1] if self.store[user] else None
        return None

# Example usage:
event_store = EventStore()
event_store.record('user1', 100)
event_store.record('user1', 200)
event_store.record('user2', 300)

print(event_store.latest('user1'))  # Output: 200
print(event_store.latest('user2'))  # Output: 300
print(event_store.latest('user3'))  # Output: None

