class Cache:
    def __init__(self):
        self.cache = {}

    def put(self, key, value):
        """Store the key-value pair in the cache."""
        self.cache[key] = value

    def get(self, key):
        """Retrieve the value for the given key if it exists in the cache."""
        return self.cache.get(key, None)

# Example usage:
